templates.body:
{
  "frames": {
{{#if atlas}}{{#each atlas.regions}}    "{{name}}": {
      "frame": { "x": {{x}}, "y": {{y}}, "w": {{width}}, "h": {{height}} },
      "rotated": {{rotated}},
      "trimmed": {{#if (or offset_x offset_y)}}true{{else}}false{{/if}},
      "spriteSourceSize": { "x": {{offset_x}}, "y": {{offset_y}}, "w": {{width}}, "h": {{height}} },
      "sourceSize": { "w": {{original_width}}, "h": {{original_height}} }
    }{{#unless @last}},{{/unless}}
{{/each}}{{/if}}  },
  "meta": {
    "app": "Ankhimate",
    "version": "1.0",
    "image": "{{#if atlas}}{{#each atlas.pages}}{{#if @first}}{{file}}{{/if}}{{/each}}{{else}}atlas.png{{/if}}",
    "format": "RGBA8888",
    "size": { {{#if atlas}}{{#each atlas.pages}}{{#if @first}}"w": {{width}}, "h": {{height}}{{/if}}{{/each}}{{else}}"w": 0, "h": 0{{/if}} },
    "scale": "1"
  }
}
